insert into bible_words (slug, term, translit, lang, gloss, theme, sense, christ, refs) values
('yeshuah','יְשׁוּעָה','Yeshuah','hebreu','Le salut, la délivrance','Le salut et la grâce','La délivrance opérée par Dieu quand l''homme est incapable de se sauver lui-même. La racine donne le nom même de Jésus, Yeshoua : « le Seigneur sauve ».','« Tu lui donneras le nom de Jésus (Yeshoua), car c''est lui qui sauvera son peuple de ses péchés. »',array['Exode 15.2','Matthieu 1.21']::text[]),
('soteria','σωτηρία','Sôtêria','grec','Le salut','Le salut et la grâce','Le salut au sens plein : être arraché au danger, guéri, préservé, rendu entier. Pas seulement pardonné, mais restauré et gardé jusqu''au bout.','« Il n''y a de salut (sôtêria) en aucun autre » : le salut est une personne, Jésus.',array['Actes 4.12','Romains 1.16']::text[]),
('chen','חֵן','Chen','hebreu','Grâce, faveur','Le salut et la grâce','La faveur imméritée, le regard bienveillant qui se penche sur celui qui ne l''a pas gagnée. « Noé trouva grâce aux yeux du Seigneur. »','En Christ, cette faveur devient définitive : « la loi par Moïse, la grâce par Jésus-Christ ».',array['Genèse 6.8','Jean 1.17']::text[]),
('rachamim','רַחֲמִים','Rachamim','hebreu','Compassion, tendresse','Le salut et la grâce','De rechem, le sein maternel : la compassion viscérale de Dieu, ses entrailles qui s''émeuvent pour l''homme comme une mère pour son enfant.','Jésus est « ému de compassion » (splagchnizomai, le mot grec des entrailles) devant les foules.',array['Ésaïe 49.15','Matthieu 9.36']::text[]),
('splagchnizomai','σπλαγχνίζομαι','Splagchnizomai','grec','Être ému de compassion','Le salut et la grâce','Litt. « être remué dans les entrailles ». La compassion qui prend aux tripes, qui met en mouvement. Le mot réservé presque uniquement à Jésus dans les Évangiles.','C''est ce que Jésus ressent devant le lépreux, la veuve, la foule sans berger : Dieu ému jusqu''aux entrailles.',array['Marc 1.41','Luc 7.13']::text[]),
('hilasterion','ἱλαστήριον','Hilastêrion','grec','Propitiatoire, expiation','Le salut et la grâce','Le couvercle d''or de l''arche, aspergé de sang au jour des Expiations, là où Dieu rencontrait l''homme. Le lieu où la colère est apaisée et la faute couverte.','Christ est notre hilastêrion : à la croix, sa vie offerte apaise le jugement et nous rouvre la présence de Dieu.',array['Lévitique 16.14','Romains 3.25']::text[]),
('kaphar','כָּפַר','Kaphar','hebreu','Expier, couvrir','Le salut et la grâce','Couvrir, effacer une faute en payant le prix exigé par la justice. Au jour du Kippour, le sang « couvrait » le péché du peuple.','Jésus accomplit l''expiation définitive : il ôte le péché du monde une fois pour toutes.',array['Lévitique 17.11','Hébreux 9.12']::text[]),
('katallage','καταλλαγή','Katallagê','grec','Réconciliation','Le salut et la grâce','Le rétablissement d''une relation brisée : deux ennemis redevenus amis. Dieu ne se contente pas de pardonner, il réconcilie et rapproche.','« Dieu nous a réconciliés avec lui par Christ » et nous confie le ministère de la réconciliation.',array['Romains 5.10','2 Corinthiens 5.18']::text[]),
('palingenesia','παλιγγενεσία','Palingenesia','grec','Régénération, nouvelle naissance','Le salut et la grâce','Une re-création : naître de nouveau, d''en haut. Non pas se corriger, mais recevoir une vie entièrement neuve par l''Esprit.','« Il faut que vous naissiez de nouveau » : la vie nouvelle donnée par Christ et l''Esprit.',array['Tite 3.5','Jean 3.3']::text[]),
('huiothesia','υἱοθεσία','Huiothesia','grec','Adoption filiale','Le salut et la grâce','Le terme juridique romain de l''adoption : un étranger reçoit pleinement le nom, l''héritage et les droits de fils. Non des serviteurs, mais des enfants.','Par Christ nous recevons l''Esprit d''adoption qui crie « Abba, Père » : héritiers de Dieu.',array['Romains 8.15','Galates 4.5']::text[]),
('teshuvah','תְּשׁוּבָה','Teshuvah','hebreu','Retour, repentance','Le salut et la grâce','Litt. « le retour ». Se retourner, revenir vers Dieu de tout son être. Non un simple regret, mais un demi-tour du cœur et de la vie.','« Revenez à moi et je reviendrai à vous » : le retour que Jésus rend possible en portant nos fautes.',array['Osée 14.2','Zacharie 1.3']::text[]),
('avon','עָוֹן','Avon','hebreu','Iniquité, faute tordue','Le salut et la grâce','La faute comme torsion, distorsion : la nature humaine tordue, courbée sur elle-même, et le poids de culpabilité qui en découle.','« Le Seigneur a fait retomber sur lui l''iniquité (avon) de nous tous » (Ésaïe 53).',array['Psaume 51.4','Ésaïe 53.6']::text[]),
('pesha','פֶּשַׁע','Pesha','hebreu','Transgression, révolte','Le salut et la grâce','Non une simple erreur, mais une rébellion volontaire : franchir la limite, se dresser contre son Maître. Le péché comme trahison d''alliance.','« Il était transpercé à cause de nos transgressions (pesha) » : Christ porte notre révolte.',array['Psaume 32.1','Ésaïe 53.5']::text[]),
('zoe','ζωή','Zôê','grec','La vie','Le salut et la grâce','Non pas la simple existence biologique (bios), mais la vie véritable, la vie de Dieu lui-même, la vie éternelle qui commence dès maintenant.','« Je suis venu pour qu''ils aient la vie (zôê) et qu''ils l''aient en abondance. »',array['Jean 10.10','Jean 1.4']::text[]),
('emunah','אֱמוּנָה','Emunah','hebreu','Foi, fidélité','La foi et l''alliance','La foi comme fidélité solide, appui ferme. Le mot dont vient « amen » : tenir bon, s''accrocher à Dieu parce qu''il est sûr.','« Le juste vivra par sa foi (emunah) » : la clé que Paul reprendra pour tout l''Évangile.',array['Habacuc 2.4','Genèse 15.6']::text[]),
('emeth','אֱמֶת','Emeth','hebreu','Vérité, fermeté','La foi et l''alliance','La vérité comme solidité, ce sur quoi on peut s''appuyer sans qu''il cède. La fidélité de Dieu qui ne trompe jamais.','Jésus est « plein de grâce et de vérité (emeth) » ; il est la vérité en personne.',array['Psaume 25.10','Jean 14.6']::text[]),
('aletheia','ἀλήθεια','Alêtheia','grec','Vérité, dévoilement','La foi et l''alliance','Litt. « ce qui n''est plus caché » : la réalité dévoilée, sans masque. La vérité qui rend libre parce qu''elle expose et guérit.','« Je suis la vérité (alêtheia)… et la vérité vous rendra libres. »',array['Jean 8.32','Jean 14.6']::text[]),
('torah','תּוֹרָה','Torah','hebreu','Instruction, loi','La foi et l''alliance','Non d''abord un code, mais une instruction paternelle : Dieu montre le chemin de la vie. La Loi comme cadeau, non comme fardeau.','Christ n''abolit pas la Torah, il l''accomplit et l''écrit dans le cœur par l''Esprit.',array['Psaume 1.2','Matthieu 5.17']::text[]),
('davar','דָּבָר','Davar','hebreu','Parole, chose, événement','La personne de Christ','Un même mot pour « parole » et « chose » : chez Dieu, dire c''est faire. Sa parole crée, agit, accomplit ce qu''elle annonce.','« La Parole (Logos, davar) a été faite chair » : Jésus est la Parole agissante de Dieu.',array['Genèse 1.3','Jean 1.14']::text[]),
('basileia','βασιλεία','Basileia','grec','Royaume, règne','La foi et l''alliance','Moins un territoire qu''un règne : là où Dieu est réellement Roi. Le Royaume déjà là en Jésus, et pas encore pleinement manifesté.','« Le Royaume de Dieu s''est approché » : il vient en la personne du Roi Jésus.',array['Marc 1.15','Matthieu 6.33']::text[]),
('kairos','καιρός','Kairos','grec','Le temps opportun','La foi et l''alliance','Non le temps qui s''écoule (chronos), mais le moment décisif, l''heure de Dieu, l''occasion à saisir.','« Le temps (kairos) est accompli » : en Christ, l''heure de Dieu a sonné.',array['Marc 1.15','Galates 4.4']::text[]),
('elpis','ἐλπίς','Elpis','grec','Espérance','La foi et l''alliance','Non un vague optimisme, mais l''attente certaine d''un bien promis par un Dieu fidèle. Une ancre de l''âme, ferme et sûre.','Christ ressuscité est « notre espérance » : elle ne trompe pas, car l''amour de Dieu est répandu en nos cœurs.',array['Romains 5.5','Hébreux 6.19']::text[]),
('kenosis','κένωσις','Kénôsis','grec','Le dépouillement','La personne de Christ','Le verbe « se vider » : le Fils, égal à Dieu, se dépouille, prend la condition de serviteur et descend jusqu''à la croix. L''abaissement volontaire de Dieu.','« Il s''est dépouillé lui-même… obéissant jusqu''à la mort de la croix. »',array['Philippiens 2.7','Jean 13.4']::text[]),
('monogenes','μονογενής','Monogenês','grec','Unique, Fils unique','La personne de Christ','L''unique de son espèce, le seul de ce genre. Jésus n''est pas un fils parmi d''autres : il est le Fils unique, engendré non créé.','« Dieu a tant aimé le monde qu''il a donné son Fils unique (monogenês). »',array['Jean 3.16','Jean 1.18']::text[]),
('soter','σωτήρ','Sôtêr','grec','Sauveur','La personne de Christ','Le titre du libérateur qui sauve d''un péril mortel. Réservé aux dieux et aux empereurs dans l''Antiquité ; l''Église le donne à Jésus seul.','« Il vous est né un Sauveur (Sôtêr), qui est le Christ, le Seigneur. »',array['Luc 2.11','Tite 2.13']::text[]),
('pleroma','πλήρωμα','Plêrôma','grec','Plénitude','La personne de Christ','La totalité, ce qui remplit entièrement. Rien ne manque en Christ : toute la plénitude de la divinité habite en lui corporellement.','« En lui habite toute la plénitude (plêrôma) de la divinité. »',array['Colossiens 2.9','Jean 1.16']::text[]),
('rabbouni','רַבּוּנִי','Rabbouni','arameen','Mon Maître','La personne de Christ','Le titre de respect le plus fort pour un maître, chargé d''affection : « mon Maître à moi ». Le cri de Marie-Madeleine au matin de Pâques.','Marie reconnaît le Ressuscité et s''écrie « Rabbouni ! » : le Maître qu''on croyait mort est vivant.',array['Jean 20.16','Marc 10.51']::text[]),
('parakletos','παράκλητος','Paraklêtos','grec','Défenseur, Consolateur','Le Saint-Esprit','Litt. « celui qu''on appelle à ses côtés » : l''avocat qui défend, le conseiller qui console, l''ami qui soutient. Un autre lui-même que Jésus envoie.','« Je prierai le Père, et il vous donnera un autre Consolateur (Paraklêtos) » : l''Esprit envoyé par Christ.',array['Jean 14.16','Jean 16.7']::text[]),
('charisma','χάρισμα','Charisma','grec','Don de grâce','Le Saint-Esprit','Un cadeau gratuit de la grâce (charis) : capacité donnée par l''Esprit pour servir les autres. Non un mérite, un don à faire fructifier.','« Chacun a reçu de Dieu un don (charisma)… mettez-le au service des autres. »',array['1 Corinthiens 12.4','1 Pierre 4.10']::text[]),
('tehillah','תְּהִלָּה','Tehillah','hebreu','Louange','Prière et louange','Le chant de louange qui célèbre Dieu pour ce qu''il est. Le titre hébreu du livre des Psaumes : « Tehillim », les louanges.','Dieu « habite les louanges (tehillah) » de son peuple ; en Christ, notre louange trouve son objet parfait.',array['Psaume 22.4','Psaume 100.4']::text[]),
('barak','בָּרַךְ','Barak','hebreu','Bénir, s''agenouiller','Prière et louange','Bénir, c''est reconnaître et proclamer le bien. La racine évoque le genou plié : bénir Dieu, c''est fléchir le genou devant lui.','En Christ, Dieu nous a « bénis de toute bénédiction spirituelle dans les lieux célestes ».',array['Psaume 103.1','Éphésiens 1.3']::text[]),
('todah','תּוֹדָה','Todah','hebreu','Action de grâce','Prière et louange','La reconnaissance qui rend grâce, souvent liée au sacrifice d''action de grâce. Dire merci à Dieu comme un acte de culte.','« Rendez grâce en toutes choses » : la todah devient le style de vie du croyant en Christ.',array['Psaume 100.4','1 Thessaloniciens 5.18']::text[]),
('chara','χαρά','Chara','grec','Joie','Prière et louange','La joie profonde, indépendante des circonstances, sœur de la grâce (charis). Un fruit de l''Esprit, non une humeur passagère.','« Que ma joie (chara) soit en vous et que votre joie soit complète » : la joie de Christ en nous.',array['Jean 15.11','Galates 5.22']::text[]),
('selah','סֶלָה','Selah','hebreu','Pause, silence (probable)','Prière et louange','Le mot mystérieux qui ponctue les Psaumes. Sens débattu : une pause musicale, un temps de silence pour peser ce qui vient d''être dit, respirer devant Dieu.','Un appel à s''arrêter et contempler : un espace pour laisser la Parole descendre dans le cœur.',array['Psaume 3.3','Psaume 46.4']::text[]),
('hosanna','הוֹשַׁע נָא','Hoshia-na (Hosanna)','hebreu','Sauve, je t''en prie !','Prière et louange','Un cri qui est à la fois supplication et acclamation : « sauve maintenant ! ». La foule le lance à Jésus entrant à Jérusalem.','« Hosanna au Fils de David ! » : la prière de salut adressée au Roi qui vient sauver.',array['Psaume 118.25','Matthieu 21.9']::text[]),
('proskuneo','προσκυνέω','Proskuneô','grec','Se prosterner, adorer','Adoration','Litt. « se prosterner pour baiser la main » : l''adoration qui s''incline, reconnaît une majesté infiniment plus grande que soi.','« Les vrais adorateurs adoreront (proskuneô) le Père en esprit et en vérité. »',array['Jean 4.23','Apocalypse 4.10']::text[]),
('latreia','λατρεία','Latreia','grec','Culte, service sacré','Adoration','Le service rendu à Dieu, le culte. Pas seulement un rite : offrir toute sa vie comme un acte d''adoration.','« Offrez vos corps… c''est là votre culte (latreia) raisonnable. »',array['Romains 12.1','Hébreux 9.14']::text[]),
('panim','פָּנִים','Panim','hebreu','Face, présence','Adoration','Le visage, et donc la présence personnelle. « Chercher la face de Dieu », c''est désirer sa présence même, pas seulement ses dons.','En Christ, « la gloire de Dieu resplendit sur la face (panim) » : voir Jésus, c''est voir le Père.',array['Psaume 27.8','2 Corinthiens 4.6']::text[]),
('or','אוֹר','Or','hebreu','Lumière','Adoration','La première parole créatrice : « Que la lumière soit ». La lumière comme vie, vérité, présence de Dieu chassant les ténèbres.','« Je suis la lumière (phôs, or) du monde » : en Jésus brille la lumière du premier matin.',array['Genèse 1.3','Jean 8.12']::text[]),
('phos','φῶς','Phôs','grec','Lumière','Adoration','La lumière qui révèle, purifie, oriente. Dieu est lumière, sans aucune ténèbre ; marcher dans la lumière, c''est vivre dans la vérité.','« En lui était la vie, et la vie était la lumière (phôs) des hommes. »',array['1 Jean 1.5','Jean 1.4']::text[]),
('soma','σῶμα','Sôma','grec','Corps','L''Église et la vie chrétienne','Le corps comme organisme vivant, chaque membre relié et nécessaire. L''image de l''Église : un seul corps, des membres différents.','« Vous êtes le corps (sôma) de Christ » dont il est la tête.',array['1 Corinthiens 12.27','Éphésiens 4.16']::text[]),
('kephale','κεφαλή','Kephalê','grec','Tête, chef','L''Église et la vie chrétienne','La tête qui dirige et donne vie au corps, la source et l''autorité. Non un tyran, mais celui qui aime et nourrit son corps.','« Christ est la tête (kephalê) de l''Église, son corps, dont il est le Sauveur. »',array['Éphésiens 5.23','Colossiens 1.18']::text[]),
('diakonos','διάκονος','Diakonos','grec','Serviteur, diacre','L''Église et la vie chrétienne','Celui qui sert à table, qui se met au service concret des autres. La grandeur du Royaume se mesure au service, non au pouvoir.','« Le Fils de l''homme est venu pour servir » : Jésus, le grand Diakonos, lave les pieds.',array['Marc 10.43','Jean 13.14']::text[]),
('martys','μάρτυς','Martys','grec','Témoin','L''Église et la vie chrétienne','Celui qui atteste ce qu''il a vu et vécu. Le mot deviendra « martyr » : témoigner jusqu''à en mourir, tant la vérité vaut la vie.','« Vous serez mes témoins (martys)… jusqu''aux extrémités de la terre. »',array['Actes 1.8','Apocalypse 2.13']::text[]),
('apostolos','ἀπόστολος','Apostolos','grec','Envoyé, apôtre','L''Église et la vie chrétienne','Un envoyé mandaté, porteur de l''autorité de celui qui l''envoie. Non un chef qui s''impose, un ambassadeur au service d''un message.','Jésus choisit douze apôtres (apostolos) pour être avec lui, puis les envoyer.',array['Marc 3.14','Éphésiens 2.20']::text[]),
('doulos','δοῦλος','Doulos','grec','Serviteur, esclave','L''Église et la vie chrétienne','L''esclave entièrement à son maître. Paul se dit fièrement « esclave de Christ » : appartenir totalement au Seigneur, c''est la vraie liberté.','Christ a pris « la condition d''esclave (doulos) » ; ses rachetés lui appartiennent avec joie.',array['Philippiens 2.7','Romains 1.1']::text[]),
('sophia','σοφία','Sophia','grec','Sagesse','L''éthique et la sagesse','La sagesse qui sait vivre selon le dessein de Dieu, non la simple intelligence. Une sagesse d''en haut, pure, pacifique, pleine de miséricorde.','« Christ, puissance de Dieu et sagesse (sophia) de Dieu. » La croix est la sagesse qui déroute le monde.',array['1 Corinthiens 1.24','Jacques 3.17']::text[]),
('gnosis','γνῶσις','Gnôsis','grec','Connaissance','L''éthique et la sagesse','La connaissance, non comme accumulation d''idées, mais comme relation. Connaître Dieu, c''est le fréquenter, non le maîtriser.','« La vie éternelle, c''est qu''ils te connaissent, toi le seul vrai Dieu, et Jésus-Christ. »',array['Jean 17.3','Philippiens 3.8']::text[]),
('yare','יִרְאָה','Yirah','hebreu','Crainte, respect','L''éthique et la sagesse','Non la peur qui fuit, mais le respect qui s''incline : reconnaître qui est Dieu et vivre en conséquence. Le début de la sagesse.','« La crainte (yirah) de l''Éternel est le commencement de la sagesse » ; en Christ, cette crainte devient adoration confiante.',array['Proverbes 9.10','Psaume 111.10']::text[]),
('mishpat','מִשְׁפָּט','Mishpat','hebreu','Droit, justice','L''éthique et la sagesse','Le droit qui défend la veuve, l''orphelin, l''étranger. La justice de Dieu qui relève l''opprimé et remet les choses droites.','« Pratique la justice (mishpat), aime la bonté, marche humblement avec ton Dieu. »',array['Michée 6.8','Ésaïe 1.17']::text[]),
('prautes','πραΰτης','Prautês','grec','Douceur, humilité','L''éthique et la sagesse','La force domptée, la puissance sous contrôle : comme un cheval fougueux devenu docile. Ni faiblesse ni mollesse, mais maîtrise paisible.','« Apprenez de moi, car je suis doux (praus) et humble de cœur. »',array['Matthieu 11.29','Galates 5.23']::text[]),
('makrothumia','μακροθυμία','Makrothumia','grec','Patience, longanimité','L''éthique et la sagesse','Litt. « la longueur d''âme » : supporter longtemps, ne pas s''enflammer, laisser du temps. La patience de Dieu qui attend le retour du pécheur.','« Le Seigneur use de patience (makrothumia)… voulant que tous parviennent à la repentance. »',array['2 Pierre 3.9','Galates 5.22']::text[]),
('egkrateia','ἐγκράτεια','Egkrateia','grec','Maîtrise de soi','L''éthique et la sagesse','Le pouvoir sur soi-même, tenir ses désirs en main plutôt que d''en être esclave. Un fruit de l''Esprit, non un simple effort de volonté.','L''Esprit produit la maîtrise de soi (egkrateia) : la liberté de ne plus être gouverné par ses pulsions.',array['Galates 5.23','2 Pierre 1.6']::text[]),
('tapeinophrosyne','ταπεινοφροσύνη','Tapeinophrosynê','grec','Humilité','L''éthique et la sagesse','Litt. « penser bas de soi » : non se rabaisser, mais cesser de se mettre au centre pour estimer l''autre supérieur à soi.','« Ayez en vous les sentiments qui étaient en Christ » qui s''est humilié jusqu''à la croix.',array['Philippiens 2.3','1 Pierre 5.5']::text[]),
('makarios','μακάριος','Makarios','grec','Heureux, bienheureux','L''éthique et la sagesse','Le bonheur profond de celui qui est comblé par Dieu, indépendant des circonstances. Le mot qui ouvre chaque Béatitude.','« Heureux (makarios) les pauvres en esprit… » : le bonheur renversé du Royaume.',array['Matthieu 5.3','Psaume 1.1']::text[]),
('leb','לֵב','Lev','hebreu','Cœur','La création et l''homme','Chez les Hébreux, le cœur n''est pas le siège des émotions mais du centre décisionnel : la volonté, la pensée, le vouloir profond. Le vrai « moi ».','Dieu promet « un cœur (lev) nouveau » ; Christ et l''Esprit l''accomplissent.',array['Proverbes 4.23','Ézéchiel 36.26']::text[]),
('adam','אָדָם','Adam','hebreu','Homme, humanité','La création et l''homme','Tiré de adamah, la terre : l''homme façonné de poussière et animé par le souffle de Dieu. À la fois humble (terre) et royal (image de Dieu).','Christ est le « dernier Adam » qui répare ce que le premier a brisé.',array['Genèse 2.7','1 Corinthiens 15.45']::text[]),
('basar','בָּשָׂר','Basar','hebreu','Chair','La création et l''homme','La chair : l''homme dans sa fragilité et sa mortalité. « Toute chair est comme l''herbe ». Non mauvaise en soi, mais faible et passagère.','« La Parole a été faite chair (sarx, basar) » : Dieu épouse notre fragilité pour la sauver.',array['Ésaïe 40.6','Jean 1.14']::text[]),
('neshamah','נְשָׁמָה','Neshamah','hebreu','Souffle de vie','La création et l''homme','Le souffle que Dieu insuffle dans les narines de l''homme pour qu''il devienne vivant. La vie comme don direct et intime de Dieu.','Le Ressuscité « souffla » sur ses disciples : « Recevez l''Esprit » — un nouveau souffle de vie.',array['Genèse 2.7','Jean 20.22']::text[]),
('tob','טוֹב','Tov','hebreu','Bon, beau, bien','La création et l''homme','Le regard de Dieu sur sa création : « cela était bon (tov) ». Bon et beau à la fois : la bonté n''est pas grise, elle est belle.','En Christ, Dieu « fait toutes choses nouvelles » et restaure la bonté première du monde.',array['Genèse 1.31','Romains 8.28']::text[]),
('anastasis','ἀνάστασις','Anastasis','grec','Résurrection','Les fins dernières','Litt. « se relever, se tenir debout à nouveau ». Non la survie d''une âme, mais le corps rappelé à la vie. Le cœur de l''espérance chrétienne.','« Je suis la résurrection (anastasis) et la vie » : Jésus ressuscité est les prémices des siens.',array['Jean 11.25','1 Corinthiens 15.20']::text[]),
('parousia','παρουσία','Parousia','grec','Venue, retour','Les fins dernières','La « présence » et l''« arrivée » d''un roi : le retour glorieux et visible du Christ. L''espérance qui oriente toute l''histoire.','« Le Seigneur lui-même descendra du ciel » : sa parousia est la ligne d''arrivée de l''histoire.',array['1 Thessaloniciens 4.16','Matthieu 24.27']::text[]),
('maranatha','מָרַנָא תָא','Marana tha','arameen','Notre Seigneur, viens !','Les fins dernières','L''une des plus vieilles prières de l''Église, gardée en araméen : « Notre Seigneur, viens ! ». Le soupir des croyants vers le retour du Christ.','« Amen, viens, Seigneur Jésus ! » : la dernière prière de la Bible fait écho au Maranatha.',array['1 Corinthiens 16.22','Apocalypse 22.20']::text[]),
('krisis','κρίσις','Krisis','grec','Jugement, séparation','Les fins dernières','Le moment où l''on tranche, où la vérité de chacun est mise en lumière. Le jugement de Dieu, juste et sans erreur, qui sépare le vrai du faux.','« Le Père a remis tout jugement (krisis) au Fils » : le Sauveur est aussi le Juste Juge.',array['Jean 5.22','Matthieu 25.31-32']::text[]),
('aion','αἰών','Aiôn','grec','Siècle, âge, éternité','Les fins dernières','Un âge, une durée, jusqu''à l''éternité. La Bible oppose « ce siècle présent » au « siècle à venir » : deux mondes, deux logiques.','En Christ commence déjà le « siècle à venir » : la vie éternelle (litt. la vie de l''aiôn) dès maintenant.',array['Éphésiens 1.21','Marc 10.30']::text[]),
('telos','τέλος','Telos','grec','But, fin, accomplissement','Les fins dernières','Non la fin qui s''arrête, mais le but qui s''accomplit : la destination visée. Vers quoi tout tend et trouve son sens.','« Tout est accompli (telos) » sur la croix : le but de l''histoire est atteint en Christ.',array['Jean 19.30','Romains 10.4']::text[])
